Item.method_code:
/*version:2*/
var itm = document.item;
var itName = aras.getItemProperty(itm,'name');
var itID = itm.getAttribute('id');
if (!itName) {
	aras.AlertError(aras.getResource('','classstructure.itemname_cannot_be_empty'), '', '', window);
	return;
}

var classStructure = aras.getItemProperty(itm, 'class_structure');

var classificationDom = aras.createXMLDocument();
if (classStructure === '') {
	classificationDom.loadXML('<class id=\'' + itID + '\'/>');
} else {
	classificationDom.loadXML(classStructure);
}

classStructure = classificationDom.xml;

var param = {};
param.aras = aras;
param.dialogType = 'class_structure';
param.isEditMode = document.isEditMode;
param.itemTypeName = itName;
param.title = aras.getResource('', 'imports_core.class_structure_for', itName);
param['class_structure'] = classStructure;
param.item = document.item;

param.dialogWidth = 600;
param.dialogHeight = 700;
param.resizable = true;
param.center = true;

param.content = 'ClassStructureDialog.html';
window.parent.ArasModules.Dialog.show('iframe', param).promise.then(function(res) {
	if (res && res != classStructure) {
		handleItemChange('class_structure', res);
	}
});

if (!aras.commonProperties.IsSSVCLicenseOk) {
	var fakeItemType = new Item('', '');
	var tmpXml = '<Item type=\'ItemType\' id=\'tmp_id_B11375B3522440E887BBF723D093F958\'>' +
			'<Relationships><Item type=\'Property\'><name>tmp_to_avoid_js_error</name></Item></Relationships></Item>';
	fakeItemType.loadAML(tmpXml);
	var param = {
		title: aras.getResource('', 'ssvc.aras_secure_social'),
		formId: 'B11375B3522440E887BBF723D093F958', //SSVC_GetLicenseMessage
		aras: aras,
		isEditMode: false,
		item: new Item('tmp_type_name_B11375B3522440E887BBF723D093F958', ''),
		itemTypeNd: fakeItemType.node,
		dialogHeight: 250, dialogWidth: 600,
		content: 'ShowFormAsADialog.html'
	};
	aras.getMostTopWindowWithAras(window).ArasModules.Dialog.show('iframe', param);
	return;
}
this.disabled = true;
var inn = aras.newIOMInnovator();
var itemTypeId = document.item.getAttribute('id');
var response = inn.applyMethod('VC_CreateDefaultTemplate', '<item_type_id>' + itemTypeId + '</item_type_id>');
if (response.isError()) {
	aras.AlertError(response);
	return;
}

if (!addActionForAddingToBookmarks(itemTypeId)) {
	return;
}

var method = aras.newIOMItem('Method', 'get');
method.setAttribute('select', 'method_code');
method.setAttribute('where', 'name=\'VC_SMButtonsPopulate\'');
method = method.apply();
if (method.isError()) {
	aras.AlertError(method);
	return;
}
var evalMethod = window.eval;
evalMethod(method.getProperty('method_code'));
var relCheckboxId = document.fieldsTab['is_relationship'].replace('span', '');
var relCheckboxNode = document.getElementById(relCheckboxId);
relCheckboxNode.setAttribute('disabled', true);

function addActionForAddingToBookmarks(typeId) {
	var actionId = getAddToBmrkActionId();
	if (!actionId) {
		return false;
	}
	if (!doesItemHaveAddToBookmarksAction(typeId, actionId)) {
		var action = aras.newIOMItem('Item Action', 'add');
		action.setProperty('source_id', typeId);
		action.setProperty('related_id', actionId);
		var result = action.apply();
		if (result.isError()) {
			aras.AlertError(result.getErrorString());
			return false;
		}
	}
	return true;
}

function getAddToBmrkActionId() {
	var actionName = 'VC_AddItemsToBookmarks';
	var action = aras.newIOMItem('Action', 'get');
	action.setProperty('name', actionName);
	var result = action.apply();
	if (result.isError()) {
		aras.AlertError(result.getErrorString());
		return false;
	} else {
		return result.getID();
	}
}

function doesItemHaveAddToBookmarksAction(itemTypeId, actionId) {
	var check = aras.newIOMItem('Item Action', 'get');
	check.setProperty('source_id', itemTypeId);
	check.setProperty('related_id', actionId);
	var result = check.apply();
	if (result.isError() || result.getItemCount() < 1) {
		return false;
	}
	return true;
}

/* Purpose is to show warning about: the PolyItem, when saved,
 drops the standard ItemType DB table in favor of a DB View,
 selecting an ItemType to be a polyitem cannot be reversed. */
var prevValueKey = 'implementation_type_previous_value_system';
var sysTa = document.getElementById(prevValueKey);
var prevValue = sysTa.value;
sysTa.value = this.value;

if (this.value == 'polymorphic' && this.value != prevValue) {
	var res = aras.confirm(aras.getResource('', 'imports_core.poly_cannot_be_reversed_to_non_poly'), window);
	if (!res) {
		handleItemChange('implementation_type', prevValue);
		sysTa.value = prevValue;
	}
}

if (prevValue == 'polymorphic' && this.value != prevValue && (document.item.getAttribute('isTemp') !== '1')) {
	aras.AlertError(aras.getResource('', 'imports_core.poly_cannot_be_reversed_to_non_poly_error'), window);
	handleItemChange('implementation_type', prevValue);
	sysTa.value = prevValue;
}

aras.evalItemMethod('ItemType Form onload', document.item);

/*version:2*/
var _form = document.forms.MainDataForm;
var _isRel = (aras.getItemProperty(document.item, 'is_relationship') == '1');
var isVersionable = (aras.getItemProperty(document.item, 'is_versionable') == '1');
var _useSrcAChb = _form.elements['use_src_access'];
var relCheckboxNode = _form.elements['is_relationship'];
var btn = _form.elements['enable_secure_social'];

if (btn) {
	btn.disabled = relCheckboxNode.checked;
	btn.style.cursor = relCheckboxNode.checked ? 'default' : 'pointer';
	btn.title = _isRel ? '"Is Relationship" itemtypes cannot be enabled for Secure Social' : '';
}

if (window.handleItemChange) {
	if (_isRel) {
		if (isVersionable) {
			handleItemChange('manual_versioning', 'BaselineVersioningDiscipline');
		}
	} else {
		handleItemChange('use_src_access', '0');
		if (isVersionable) {
			handleItemChange('manual_versioning', '0');
		}
	}
}
if (_useSrcAChb) {
	_useSrcAChb.disabled = !_isRel;
}

/*version: 5*/
var _mv_chb = getFieldComponentByName('versioning_discipline');
var _isVers = (aras.getItemProperty(item, 'is_versionable') === '1');
var item = document.item;
if (window.handleItemChange) {
	if (_isVers) {
		var isRelationship = (aras.getItemProperty(item, 'is_relationship') == '1');
		var versioningDiscipline = isRelationship ? 'BaselineVersioningDiscipline' : '0';
		handleItemChange('manual_versioning', versioningDiscipline);
	} else {
		handleItemChange('manual_versioning', '');
		aras.setItemPropertyAttribute(item, 'manual_versioning', 'is_null', '1');
	}
}
if (_mv_chb) {
	_mv_chb.setDisabled(_isVers);
}

var docItem = document.item;
if (docItem) {
	var newItemTypeName = srcElement.value;
	if (!newItemTypeName) {
		aras.AlertError(aras.getResource('', 'classstructure.itemname_cannot_be_empty'));
		srcElement.value = aras.getItemProperty(docItem, 'name');
		return;
	}
}

var isRelship = aras.getItemProperty(document.item, 'is_relationship') == '1';
var implementationType = aras.getItemProperty(document.item, 'implementation_type');
var isPolymorphicOrFederated = implementationType == 'polymorphic' || implementationType == 'federated';
var isFileIT = aras.getItemProperty(document.item, 'name') == 'File';
var isNew = window.aras.isNew(document.item);
var isLicenseOk = aras.commonProperties.IsSSVCLicenseOk;

if (!isRelship && !isPolymorphicOrFederated && !isFileIT && !isNew && isLicenseOk) {
	var itemTypeId = document.item ? document.item.getAttribute('id') : inArgs.itemTypeId;
	var itm = aras.newIOMItem('DiscussionTemplate', 'get');
	itm.setAttribute('select', 'id');
	itm.setProperty('source_id', itemTypeId);
	itm = itm.apply();
}

var isDisable = !document.isEditMode || isRelship || isNew || isPolymorphicOrFederated || isFileIT;
setButtonStyle('enable_secure_social', itm ? itm.getItemCount() === 0 : true, isDisable);
setButtonStyle('already_ssvc_enabled', itm ? itm.getItemCount() !== 0 : false, true);

function setButtonStyle(name, isDisplay, isDisable) {
	var btn = document.getElementsByTagName('input')[name];
	if (btn) {
		btn.style.display = isDisplay ? '' : 'none';
		btn.disabled = isDisable;
		btn.style.cursor = isDisable ? 'default' : 'pointer';
		btn.title = (isDisplay && isRelship) ? '"Is Relationship" itemtypes cannot be enabled for Secure Social' : '';
	}
	if (isDisplay && !isDisable) {
		setIsRelationshipCheckboxEnabled(name != 'enable_secure_social');
	}
}

function setIsRelationshipCheckboxEnabled(isSSEnabled) {
	var relCheckboxId = document.fieldsTab['is_relationship'].replace('span', '');
	var relCheckboxNode = document.getElementById(relCheckboxId);
	if (isSSEnabled) {
		relCheckboxNode.setAttribute('disabled', true);
	} else {
		relCheckboxNode.removeAttribute('disabled');
	}
}

var _mv_chb_id = document.fieldsTab && document.fieldsTab['versioning_discipline'] && document.fieldsTab['versioning_discipline'].slice(0, -4);
var _usaChb_id = document.fieldsTab && document.fieldsTab['use_src_access'] && document.fieldsTab['use_src_access'].slice(0, -4);

window['expression_' + _mv_chb_id + '_setExpression'] = function(isEditMode) {
	var _mv_chb = window['field' + _mv_chb_id + 'Component'];
	var _isVers = (aras.getItemProperty(document.item, 'is_versionable') === '1');
	_mv_chb.setReadOnly(!isEditMode || !_isVers);
};

window['expression_' + _usaChb_id + '_setExpression'] = function(isEditMode) {
	var _usa_chb = document.getElementById(_usaChb_id);
	var _isRel = (aras.getItemProperty(document.item, 'is_relationship') === '1');
	_usa_chb.disabled = (!isEditMode || !_isRel);
};

window['expression_' + _mv_chb_id + '_setExpression'](document.isEditMode);
window['expression_' + _usaChb_id + '_setExpression'](document.isEditMode);

aras.getMostTopWindowWithAras(window)['system_ItemTypeHideTabs'] = function() {
	// Used as onload event for ItemType Form.
	// Make sure there is a relationships frame
	if (!parent.relationships) {
		setTimeout(function() {
			aras.getMostTopWindowWithAras(window)['system_ItemTypeHideTabs']();
		}, 100);
		return;
	}

	var tabsToHide = {
		'polymorphic': ['Allowed Permission', 'Allowed Workflow', 'Client Event', 'Item Action', 'Item Report',
			'RelationshipType', 'View', 'DiscussionTemplate', 'ItemType_xPropertyDefinition'],
		'federated': ['DiscussionTemplate', 'Morphae', 'ItemType_xPropertyDefinition'],
		'table': ['Morphae', 'xItemTypeAllowedProperty'] //What is table? In UI it's called "Single Item"
	};

	//disable xItemTypeAllowedProperty relationships tab for xPropertyContainerItem item type
	if (document.itemID === '2073428E99384916938E3519AF1C0A44') {
		tabsToHide.polymorphic.push('xItemTypeAllowedProperty');
	}

	function getNameToIdDictionary(tabsObj) {
		var dictionary = [];
		var keys = Object.keys(tabsObj);
		keys.forEach(function(key) {
			var tabs = tabsObj[key];
			tabs.forEach(function(el) {
				if (!dictionary[el]) {
					dictionary[el] = aras.getRelationshipTypeId(el);
				}
			});
		});

		return dictionary;
	}

	if (parent.relationships.document.readyState != 'complete' || !parent.relationships.currTabID) {
		setTimeout(function() {
			aras.getMostTopWindowWithAras(window)['system_ItemTypeHideTabs']();
		}, 100);
	} else {
		var implementationType = parent.item.selectSingleNode('implementation_type');
		var implementationTypeText = '';
		if (implementationType) {
			implementationTypeText = implementationType.text;
		}

		var relationshipTypesDictionary = getNameToIdDictionary(tabsToHide);

		parent.relationships.relTabbar.getTabOrder().split(',').forEach(function(tabId) {
			parent.relationships.relTabbar.setTabEnabled(tabId, 1);
		});

		tabsToHide[implementationTypeText].forEach(function(tabName) {
			parent.relationships.relTabbar.setTabEnabled(relationshipTypesDictionary[tabName], 0);
		});

		var tabIds = parent.relationships.relTabbar.getTabOrder('|');
		var a = tabIds.split('|');
		// Show the first tab
		parent.relationships.relTabbar.selectTab(a[0]);
	}
};

// Wait a bit before starting
setTimeout(function() {
	aras.getMostTopWindowWithAras(window)['system_ItemTypeHideTabs']();
}, 200);
